/**
 * Expanded question bank — 750 hand-written questions added to grow the daily
 * and practice pools. The later batches broaden the mix toward modern pop
 * culture — movies, TV, video games, music, tech, and internet culture —
 * alongside the evergreen topics. The three most recent batches of 50 pull
 * back the other way to even out the category mix: they feed the thin
 * categories (Nature most of all, then art, the human body, mythology,
 * literature, internet, pop culture, and technology) while keeping a
 * pop-culture share, since the practice
 * picker steers away from repeating a category and a lopsided bank makes that
 * harder.
 *
 * Most of these were written to the older spec §2.2 rules, which put
 * misdirection first, so many were easier than we now want. Between
 * 2026-10-04 and 2026-10-11, 547 of them were rewritten to the current rules
 * with pipeline/fix-clues.ts, in eight rounds. The other 3 were already judged
 * good. The before and after, with a source for each new fact, are in
 * clueEval/results/rewrites-2026-10-04.json (round 1),
 * rewrites-2026-10-04-round-2.json (round 2), rewrites-2026-10-05.json
 * (round 3), rewrites-2026-10-10.json (round 4),
 * rewrites-2026-10-10-round-5.json, -round-6.json, -round-7.json and
 * rewrites-2026-10-11-round-8.json. Round 9 (rewrites-2026-10-11-round-9.json)
 * rewrote the questions still judged "needs work". Round 10
 * (rewrites-2026-10-11-round-10.json) rewrote 50 questions judged good whose
 * clues 1-3 included one the judge scored only 2 or 3 of 5 for interest.
 * The last 100 (from "tulip" on) were added on 2026-10-12, written to the
 * current rules from the start and weighted to the thin categories. Each was
 * fact-checked against its sources and judged, and the ones that fell short
 * were rewritten; the sources are in clueEval/results/new-questions-2026-10-12.json.
 * The 50 after those (from "napster" on) were added later the same day the same
 * way, again for the thinnest categories; their sources are in
 * clueEval/results/new-questions-2026-10-12-round-2.json.
 * The 50 after those (from "gullivers-travels" on) were added on 2026-10-15
 * the same way, spread across the 13 thinnest categories; their sources are in
 * clueEval/results/new-questions-2026-10-15.json.
 * The current rules
 * for writing and rewriting clues are in lib/questions/README.md, under "What
 * makes a good question". Follow those, not the style of the entries below.
 *
 * These merge into the local bank after SEED_QUESTIONS and (when present) the
 * gitignored private bank. They are validated by the same integrity suite.
 */

